func resetCredentialEnv(t *testing.T) (home, configPath string) {
	t.Helper()
	home = t.TempDir()
	t.Setenv("HOME", home)
	for _, name := range []string{
		"FORKABLE_CONFIG",
		"FORKABLE_CONFIG_DIR",
		"FORKABLE_DATA_DIR",
		"FORKABLE_STATE_DIR",
		"FORKABLE_CACHE_DIR",
		"FORKABLE_HOME",
		"XDG_CONFIG_HOME",
		"XDG_DATA_HOME",
		"XDG_STATE_HOME",
		"XDG_CACHE_HOME",
	} {
		t.Setenv(name, "")
	}
	if restore, err := cliutil.SetHomeOverride(""); err == nil {
		t.Cleanup(restore)
	} else {
		t.Fatalf("reset home override: %v", err)
	}
	return home, filepath.Join(home, ".config", "forkable-pp-cli", "config.toml")
}

